/** The JSON object a record holds. Its shape is the app's own. */
export type RecordData = Record<string, unknown>

/** One record of the signed-in customer in a collection the app declares. */
export interface AppRecord<T extends RecordData = RecordData> {
  /** Unique per customer within the collection: chosen by the app, or generated by `create`. */
  key: string
  data: T
  /** Starts at 1 and rises by one on every replacement. */
  version: number
  createdAt: string
  updatedAt: string
}

/**
 * A written record. While the owner previews the app as a customer nothing is
 * saved: the record comes back as it would have been, with `simulated: true`.
 */
export type RecordWriteResult<T extends RecordData = RecordData> = AppRecord<T> & {
  simulated?: true
}

/** One page of records. Pass `meta.nextCursor` back as `cursor`; null means the end. */
export interface RecordPage<T extends RecordData = RecordData> {
  data: Array<AppRecord<T>>
  meta: { nextCursor: string | null }
}

/**
 * Filters of `records(name).list`. Without `index` the most recently changed
 * records come first. With `index` (a field declared under the collection's
 * `indexes` in `marcapony.json`) the list is ordered by that field and takes
 * one filter: `eq` for any index type, `prefix` for a string index, `gte` and
 * `lte` (inclusive, alone or together) for a number or date index.
 */
export interface ListRecordsParams {
  index?: string
  eq?: string | number | boolean
  prefix?: string
  gte?: string | number
  lte?: string | number
  /** Defaults to `desc` without an index and `asc` with one. */
  order?: 'asc' | 'desc'
  /** 1 to 100, 25 by default. */
  limit?: number
  /** `meta.nextCursor` of the previous page of the same query. */
  cursor?: string
}

export interface PutRecordOptions {
  /** Write only if the record is at this version; otherwise `ConflictError`. Without it the last write wins. */
  ifVersion?: number
  /** Replay guard for a retried write; the server holds it 48h. */
  idempotencyKey?: string
}

export interface DeleteRecordOptions {
  /** Delete only if the record is at this version; otherwise `ConflictError`. */
  ifVersion?: number
}
